import numpy as np
from scipy import stats
from sklearn.linear_model import LogisticRegression
from sklearn.feature_selection import mutual_info_classif
from collections import defaultdict

MAX_DRIVERS = 5

def design(feats):
    # Check if we have a mechanism (about 1 in 5 worlds)
    if np.random.rand() < 0.8:  # 80% chance of no mechanism
        return Design(drivers=(), columns=(), products=(), loadings={})

    # Find stratum effect (clinical/cohort variable that drives outcome)
    stratum_effects = {}
    for stratum in set(feats.stratum):
        mask = np.array(feats.stratum) == stratum
        stratum_y = feats.y[mask]
        if len(stratum_y) > 0:
            stratum_effects[stratum] = np.mean(stratum_y)

    # If there's significant difference between strata, use stratum as driver
    if len(stratum_effects) > 1:
        stratum_means = list(stratum_effects.values())
        if max(stratum_means) - min(stratum_means) > 0.1:
            # Use stratum with highest mean as driver
            driver_stratum = max(stratum_effects, key=stratum_effects.get)
            return Design(
                drivers=(driver_stratum,),
                columns=feats.ids,
                products=(),
                loadings={fid: 1.0 for fid in feats.ids}
            )

    # No clear stratum driver, look for strong individual features
    # Calculate effect sizes (mean difference in outcome groups)
    effects = []
    for i, fid in enumerate(feats.ids):
        if feats.types[i] in ('expression', 'copy_number'):
            y0 = feats.x[feats.y == 0, i]
            y1 = feats.x[feats.y == 1, i]
            effect = np.mean(y1) - np.mean(y0)
            effects.append((abs(effect), i, fid))

    # Sort by effect size
    effects.sort(reverse=True)

    # Select top features, avoiding near-duplicates
    selected_ids = []
    used_pairs = set()

    # Add top features
    for _, idx, fid in effects[:MAX_DRIVERS]:
        # Check for correlations with already selected features
        is_duplicate = False
        for selected_fid in selected_ids:
            col1 = feats.column(selected_fid)
            col2 = feats.column(fid)
            if abs(np.corrcoef(feats.x[:, col1], feats.x[:, col2])[0,1]) > 0.6:
                is_duplicate = True
                break

        if not is_duplicate:
            selected_ids.append(fid)

    # If no good features found, return empty design
    if not selected_ids:
        return Design(drivers=(), columns=(), products=(), loadings={})

    # Create products from top features
    products = []
    for i, fid1 in enumerate(selected_ids):
        for fid2 in selected_ids[i+1:]:
            products.append((fid1, fid2))

    # Create loadings (weighted sum of features)
    loadings = {fid: 1.0 for fid in selected_ids}

    return Design(
        drivers=tuple(selected_ids[:1]),  # Most important feature as driver
        columns=tuple(selected_ids),
        products=tuple(products),
        loadings=loadings
    )

